import sys, json, numpy as np
import anndata as ad
import scipy.sparse as sp

sys.path.extend(['storage/system', 'storage/praxis'])

# Frozen Praxis embedding path
from mpb_graphfwpca_override import eliminate_mpb_graphfwpca as run_frozen
# Soft inbound-degree kNN builder
from daqb_soft_inbound import knn_soft_inbound

# Metrics wrapper tolerant to API variants
import openproblems_metrics as MET

ORDER = [
    "ASW_batch","ASW_label","ARI","NMI","Graph_conn",
    "kBET","iLISI","cLISI","PCR","Cell_cycle"
]

def _safe_float(x):
    try: return float(x)
    except Exception: return float('nan')

def safe_eval_metrics(B: ad.AnnData):
    try:
        if hasattr(MET, "compute_raw_metrics") and hasattr(MET, "normalize_metrics") and hasattr(MET, "final_score"):
            raw = MET.compute_raw_metrics(B); norm = MET.normalize_metrics(raw); score = MET.final_score(norm)
            return raw, norm, _safe_float(score)
        if hasattr(MET, "evaluate"):
            res = MET.evaluate(B)
            if isinstance(res, dict):
                raw = res.get("raw") or res.get("raw_metrics") or {}
                norm = res.get("normalized") or res.get("norm_metrics") or {}
                score = res.get("score") or res.get("overall") or float('nan')
                return raw, norm, _safe_float(score)
        if hasattr(MET, "compute_metrics"):
            raw = MET.compute_metrics(B)
            norm = MET.normalize_metrics(raw) if hasattr(MET, "normalize_metrics") else {}
            score = MET.final_score(norm) if hasattr(MET, "final_score") else float('nan')
            return raw, norm, _safe_float(score)
    except Exception as e:
        print("SAFE_METRICS_WARNING:", repr(e))
    return {}, {}, float('nan')

def _degree_stats(C: sp.csr_matrix):
    deg = np.asarray(C.sum(axis=1)).ravel()
    def _gini(x):
        x = np.asarray(x, dtype=float)
        if np.all(x == 0) or x.size == 0: return 0.0
        x = np.sort(x); n = x.size; cum = np.cumsum(x)
        return float((n + 1 - 2 * np.sum(cum) / cum[-1]) / n)
    q95 = float(np.quantile(deg, 0.95)) if deg.size else 0.0
    q99 = float(np.quantile(deg, 0.99)) if deg.size else 0.0
    stats = {
        "n": int(deg.size),
        "mean": float(deg.mean()) if deg.size else 0.0,
        "median": float(np.median(deg)) if deg.size else 0.0,
        "min": float(deg.min()) if deg.size else 0.0,
        "max": float(deg.max()) if deg.size else 0.0,
        "std": float(deg.std()) if deg.size else 0.0,
        "p95": q95, "p99": q99, "gini": _gini(deg),
    }
    return stats

# Frozen Praxis config (embedding path only; graph replaced by soft-inbound)
FROZEN_CFG = dict(
    lam_override=0.605, delta=0.12, kdensity=22, k_total=50,
    emb_n_neighbors=17, gamma_max=0.70, cap=2.0, rng_seed=0
)

# Soft inbound-degree parameters
SOFT_CFG = dict(
    k=50, k_candidates=1280, metric="cosine",
    alpha=0.15, cap_in=100.0, tau=30.0,
    equal_quota=False
)

def test(adata: ad.AnnData):
    # 1) Run frozen Praxis to obtain embedding (X_emb)
    A = run_frozen(adata.copy(), **FROZEN_CFG)
    assert 'X_emb' in A.obsm, "Expected embedding in obsm['X_emb']"

    # 2) Build DAQB-style graph with soft inbound-degree control
    batches = np.asarray(A.obs['batch']).astype(str)
    C, D = knn_soft_inbound(
        Z=np.asarray(A.obsm['X_emb']),
        batches=batches,
        **SOFT_CFG
    )

    # 3) Attach graph to AnnData; set neighbors meta
    A.obsp['connectivities'] = C
    A.obsp['distances'] = D
    A.uns['neighbors'] = {
        'connectivities_key': 'connectivities',
        'distances_key': 'distances',
        'params': {'n_neighbors': int(SOFT_CFG['k']), 'method': 'soft_inbound_daqb', 'metric': SOFT_CFG['metric']}
    }

    # 4) Diagnostics
    print("SOFT_INBOUND_PARAMS:", json.dumps({
        "alpha": SOFT_CFG['alpha'], "cap_in": SOFT_CFG['cap_in'],
        "tau": SOFT_CFG['tau'], "k_candidates": SOFT_CFG['k_candidates'],
        "k": SOFT_CFG['k'], "metric": SOFT_CFG['metric'],
        "equal_quota": bool(SOFT_CFG['equal_quota'])
    }))
    deg_stats = _degree_stats(C)
    print("DEGREE_JSON:", json.dumps(deg_stats))

    # 5) Metrics (normalized+raw) in task order
    raw, norm, score = safe_eval_metrics(A)
    def fmt_panel(panel):
        return "  " + "  ".join([f"{k}: {panel.get(k, float('nan')):.3f}" for k in ORDER])
    print("Normalized [0-1] (task order):")
    print(fmt_panel(norm))
    print("Raw (task order):")
    print(fmt_panel(raw))
    print(f"Overall (mean of 10 normalized): {score:.6f}")

    # 6) Emit JSON summary for archival
    out = dict(
        method="soft_inbound_daqb",
        frozen_cfg=FROZEN_CFG, soft_cfg=SOFT_CFG,
        degree=deg_stats,
        normalized={k: _safe_float(norm.get(k, np.nan)) for k in ORDER},
        raw={k: _safe_float(raw.get(k, np.nan)) for k in ORDER},
        overall=_safe_float(score),
    )
    print("SOFT_INBOUND_SUMMARY_JSON:", json.dumps(out))
    return "Soft inbound-degree DAQB diagnostics completed (test mode)"
